// src/pages/AdminPage.jsx
import React, { useState, useEffect } from 'react';
// import api from '../api'; // Tạm thời chưa cần api
import './AdminPage.css'; // 👈 Import CSS ở đây là đúng

// DỮ LIỆU GIẢ (MOCK DATA)
const mockUsers = [
  { _id: '1', name: 'Tuấn Anh (Admin)', email: 'admin@example.com', role: 'admin' },
  { _id: '2', name: 'Nguyễn Văn A', email: 'vana@example.com', role: 'user' },
  { _id: '3', name: 'Trần Thị B', email: 'thib@example.com', role: 'user' },
  { _id: '4d', name: 'Lê Văn C', email: 'vanc@example.com', role: 'user' },
];

function AdminPage() {
  const [users, setUsers] = useState([]);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [isLoading, setIsLoading] = useState(true);

  // 1. Lấy danh sách người dùng (DÙNG DỮ LIỆU GIẢ)
  useEffect(() => {
    setIsLoading(true);
    // Giả lập việc gọi API mất 0.5 giây
    setTimeout(() => {
      setUsers(mockUsers);
      setIsLoading(false);
    }, 500);
  }, []);

  // 2. Xử lý xóa người dùng (XÓA DỮ LIỆU GIẢ)
  const handleDelete = (userId) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa người dùng này?')) {
      // Giả lập việc xóa thành công
      // Cập nhật lại danh sách 'users' trên giao diện
      setUsers(users.filter(user => user._id !== userId));
      setMessage({ text: '✔ Xóa người dùng (giả) thành công!', type: 'success' });
    }
  };

  if (isLoading) {
    return <div>Đang tải danh sách người dùng...</div>;
  }

  // Phần JSX (HTML) giữ nguyên
  return (
    <div className="admin-container">
      <h2>Quản lý Người dùng</h2>
      {message.text && (
        <div className={`message-box ${message.type}`}>{message.text}</div>
      )}
      <table className="users-table">
        <thead>
          <tr>
            <th>Tên</th>
            <th>Email</th>
            <th>Quyền (Role)</th>
            <th>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {users.map(user => (
            <tr key={user._id}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
              <td>
                <button 
                  className="btn-delete"
                  onClick={() => handleDelete(user._id)}
                >
                  Xóa
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default AdminPage;
